mapper.select:
SELECT T.*, IFNULL(sysProjectFunctionDefaultLabel, 0) sysProjectFunctionDefault FROM (
  SELECT sp.*,
  (SELECT group_concat(sdi.sys_dict_item_name) FROM sys_project_default spd
  INNER JOIN sys_dict_item sdi ON spd.sys_project_default_type = sdi.sys_dict_item_id
  WHERE spd.sys_project_id = sp.sys_project_id) sysProjectFunctionDefaultLabel
  FROM sys_project sp



              AND sys_project_group = #{request.sysProjectGroup}



        AND sys_project_dict_item_id = #{request.sysProjectDictItemId}



        AND FIND_IN_SET(#{request.sysProjectFunction}, sys_project_function)



) T ORDER BY sysProjectFunctionDefaultLabel DESC
